		private bool CanReceivePlayerSkill(int stationIndex) {
			if (networkPtr.MatchingType != Dpr.NetworkUtils.MatchingType.Password && currentState == SelectState.WaitLotteryCategoryAndRank)
				return true;

			ContestUtils.EmitLog(string.Format("Receive Skill Point Data in state {0}. from Station{1}", currentState, stationIndex), UnityEngine.LogType.Error);
