		private void LotCategoryAndRankBySkill() {
			int totalPoint = CalcTotalPlayerSkillPoint();
			int receiveCount = GetReceiveCount();
			ContestUtils.EmitLog(string.Format("LotCategoryAndRankBySkill : TotalPoint [{0}] : ReceiveCount [{1}]", totalPoint, receiveCount), UnityEngine.LogType.Log);
			ContestWork.categoryID = ContestUtils.LotteryCategory(bIsAllMemberDpClear);
			ContestWork.rankID = LotteryEntryRankBySkillPoint((float)totalPoint / (float)receiveCount);
			ContestWork.cassetVersion = PlayerWork.cassetVersion;
			ContestUtils.EmitLog(string.Format("Lot Category And Rank :Category  [{0}] - Rank [{1}]", ContestWork.categoryID, ContestWork.rankID), UnityEngine.LogType.Log);
		}
		private int CalcTotalPlayerSkillPoint() {
			int total = 0;
			for (int i = 0; i < receiveSkillPointArray.Length; i++)
			{
				if (networkPtr.IsGamerActive(i))
					total += receiveSkillPointArray[i];
			}
			return total;
		}
		private global::Dpr.Contest.RankID LotteryEntryRankBySkillPoint(float aveSkillPoint) {
			ContestUtils.EmitLog(string.Format("Start Lottery Entry Rank : AveSkillPoint  [{0}]", aveSkillPoint), UnityEngine.LogType.Log);
			foreach (ContestConfigDatas.SheetLotteryEntryRank entryRank in contConfigDataPtr.LotteryEntryRank)
			{
				if (aveSkillPoint <= entryRank.aveSkillPoint)
					return entryRank.contestRank;
			}

			ContestUtils.EmitLog(string.Format("AveSkillpoint over max aveSkillpoin in MasterData : {0}", aveSkillPoint), UnityEngine.LogType.Error);
			return RankID.NULL;
		}
		private void LotRandomCategoryAndRank() {
			ContestWork.categoryID = ContestUtils.LotteryCategory(bIsAllMemberDpClear);
			ContestWork.rankID = ContestUtils.LotteryCategory(ContestWork.categoryID);
			ContestWork.cassetVersion = PlayerWork.cassetVersion;
			ContestUtils.EmitLog(string.Format("Lot Category And Rank :Category  [{0}] - Rank [{1}]", ContestWork.categoryID, ContestWork.rankID), UnityEngine.LogType.Log);
		}
		private string[] GetCanEntryCategoryName() {
			categoryIds = ContestUtils.GetCanEntryCategory(PlayerWork.playerStatus.dp_clear);
			string[] names = new string[categoryIds.Length + 1];
			for (int i = 0; i < categoryIds.Length; i++)
				names[i] = ContestUtils.GetCategoryNameByID(categoryIds[i]);

			names[names.Length - 1] = msgFile.GetNameStr("DP_contest_594");
			return names;
		}
		private string[] GetCanEntryRankName(global::Dpr.Contest.CategoryID categoryID) {
			rankIds = ContestUtils.GetRankIDsByCategoryID(categoryID);
			if (rankIds.Length == 0)
				return null;

			string[] names;
			if (rankIds.Length > 1)
			{
				names = new string[rankIds.Length + 1];
				int i;
				for (i = 0; i < rankIds.Length; i++)
					names[i] = ContestUtils.GetRankNameByID(rankIds[i]);

				names[i] = msgFile.GetNameStr("DP_contest_594");
			}
			else
			{
				names = new string[rankIds.Length];
				for (int i = 0; i < rankIds.Length; i++)
					names[i] = ContestUtils.GetRankNameByID(rankIds[i]);
			}
			return names;
		}
		private void DecideCategoryAndRank() {
