		private void UpdateWaitAllPlayerReady(float deltaTime) {
			if (networkPtr.IsHost())
			{
				if (networkPtr.IsAllMainFlagTrue(networkPtr.JoinMemberNum))
				{
					currentState = SelectState.Finish;
					networkPtr.ResetTimer();
					ContestUtils.EmitLog("Decide Entry Contest", UnityEngine.LogType.Log);
					networkPtr.SendNoticeDataToAll(NoticeID.DecideEntry);
				}
			}
			else
			{
				networkPtr.RepeatSendNotice(NoticeID.Ready, deltaTime);
			}
		}
		private void UpdateFinish(float deltaTime) {
