				networkPtr.IsFinishWait(deltaTime))
			{
				onFinishState?.Invoke();
			}
		}
		public void OnLeaveOtherPlayer(int stationIndex) {
			if (!bIsActive)
				return;

			if (!networkPtr.IsJoinedOtherPlayer())
			{
				bIsActive = false;
				if (selectorWindowPtr.IsOpen)
					selectorWindowPtr.SetWindowActive(false);

				onFinish?.Invoke(ContestMatching.FinishPattern.LeavedMember);
				return;
			}

			networkPtr.SetMainFlag(stationIndex, true);
			contestMatchingUIPtr.OnExitPlayer(stationIndex);
			ContestUtils.EmitLog(string.Format("MatchingType : {0}", networkPtr.MatchingType), UnityEngine.LogType.Log);
			if (networkPtr.MatchingType != Dpr.NetworkUtils.MatchingType.Password)
			{
				receiveSkillPointArray[stationIndex] = 0;
				return;
			}

			ContestUtils.EmitLog(string.Format("NowSelectPlayerIndex : {0}", nowSelectPlayerIndex), UnityEngine.LogType.Log);
			if (transferPlayerIndex < 0)
			{
				ContestUtils.EmitLog("Not Select Turn", UnityEngine.LogType.Log);
			}
			else if (transferPlayerIndex != stationIndex)
			{
				ContestUtils.EmitLog(string.Format("Tranfer Player Index [{0}] - Leave Player Index [{1}]", transferPlayerIndex, stationIndex), UnityEngine.LogType.Log);
			}
			else if (nowSelectPlayerIndex != stationIndex)
			{
				ContestUtils.EmitLog(string.Format("Now Select Player Index [{0}] - Leave Player Index [{1}]", nowSelectPlayerIndex, stationIndex), UnityEngine.LogType.Log);
			}
			else
			{
				TransforNextPlayer(stationIndex + 1);
			}
		}
		public void OnChangeHostMine() {
			if (!networkPtr.IsJoinedOtherPlayer())
			{
				bIsActive = false;
				return;
			}

			ContestUtils.EmitLog(string.Format("Change Host Mine : State [{0}]", currentState), UnityEngine.LogType.Log);
			networkPtr.SetMainFlag(networkPtr.MyStationIndex, true);
			if (networkPtr.MatchingType != Dpr.NetworkUtils.MatchingType.Password)
				receiveSkillPointArray[networkPtr.MyStationIndex] = GetSkillPoint(networkPtr.PlayerSkill);

			if (currentState == SelectState.SelectCategoryAndRank)
			{
				initSelectPlayerIndex = networkPtr.MyStationIndex;
				contestMatchingUIPtr.StartCountDown(contestMatchingUIPtr.CountTime);
				if (nowSelectPlayerIndex != networkPtr.MyStationIndex)
				{
					if (bIsAlreadySelected)
						TransforNextPlayer(networkPtr.MyStationIndex + 1);
					else
						StartSelectCategoryAndRank();
				}
			}
		}
		private int GetSkillPoint(global::Dpr.Contest.PlayerSkill skillID) {
			return contConfigDataPtr.MatchingSkill[(int)skillID].skillPoint;
		}
		public void OnChangeHostOtherPlayer() {
			if (bIsActive && networkPtr.MatchingType != Dpr.NetworkUtils.MatchingType.Password && currentState == SelectState.WaitLotteryCategoryAndRank)
				networkPtr.SendSkillPointDataToHost();
		}
		public void Deactivate() {
			ContestUtils.EmitLog(string.Format("OnSessionError!! : State : {0}", currentState), UnityEngine.LogType.Log);
			bIsActive = false;
			transferPlayerIndex = -1;
			if (selectorWindowPtr == null)
				return;

			if (selectorWindowPtr.IsOpen)
				selectorWindowPtr.Close();
		}
		public void OnReceiveCountDownData(global::Dpr.Contest.CountDownNetData timeData) {
