		public void OnReceiveCategoryAndRank(global::Dpr.Contest.CategoryAndRankNetData categoryAndRankData) {
			ContestWork.categoryID = (CategoryID)categoryAndRankData.data.category;
			ContestWork.rankID = (RankID)categoryAndRankData.data.rank;
			ContestWork.cassetVersion = categoryAndRankData.data.cassetVersion;
			ContestUtils.EmitLog(string.Format("Receive Category And Rank :Category  [{0}] - Rank [{1}]", ContestWork.categoryID, ContestWork.rankID), UnityEngine.LogType.Log);
			DecideCategoryAndRank();
			if (networkPtr.IsHost())
				networkPtr.SetMainFlag(networkPtr.MyStationIndex, true);
			else
				networkPtr.SendNoticeData(NoticeID.Ready);
		}
		public void OnReceiveReadyData(int stationIndex, global::Dpr.Contest.NoticeID noticeID) {
			ContestUtils.EmitLog(string.Format("Receive Notice {0} from Station{1}", noticeID, stationIndex), UnityEngine.LogType.Log);
			switch (noticeID)
			{
				case NoticeID.Ready:
					networkPtr.SetMainFlag(stationIndex, true);
					break;
				case NoticeID.DecideEntry:
					networkPtr.ResetTimer();
					currentState = SelectState.Finish;
					break;
				case NoticeID.DoNextStep:
					if (networkPtr.IsHost())
						ContestUtils.EmitLog("Receive Notice [DoNextStep] : Host", UnityEngine.LogType.Error);
					else
						onFinishState?.Invoke();
					break;
			}
		}
		private void SendDecideCategoryAndRank() {
			networkPtr.SendCategoryAndRankDataToAll(ContestWork.categoryID, ContestWork.rankID, PlayerWork.cassetVersion);
			networkPtr.SetMainFlag(networkPtr.MyStationIndex, true);
		}
		public ContestMatchingCategoryAndRank() { }
		private enum SelectState
		{
			WaitLotteryCategoryAndRank = 0,
			SelectCategoryAndRank = 1,
			WaitAllPlayerReady = 2,
